#include <string>

class Solution {
public:
    int numWays(std::string s) {
        const int MOD = 1e9 + 7;
        long long total = 0, n = s.size();
        for (char c : s) if (c == '1') total++;
        if (total % 3 != 0) return 0;
        if (total == 0) return ((n - 1) * (n - 2) / 2) % MOD;
        long long k = total / 3, ones = 0, ways1 = 0, ways2 = 0;
        for (char c : s) {
            if (c == '1') ones++;
            if (ones == k) ways1++;
            else if (ones == 2 * k) ways2++;
        }
        return (ways1 * ways2) % MOD;
    }
};

class Solution {
    public int numWays(String s) {
        final int MOD = 1000000007;
        long total = 0, n = s.length();
        for (int i = 0; i < n; i++) if (s.charAt(i) == '1') total++;
        if (total % 3 != 0) return 0;
        if (total == 0) return (int)(((n - 1) * (n - 2) / 2) % MOD);
        long k = total / 3, ones = 0, ways1 = 0, ways2 = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '1') ones++;
            if (ones == k) ways1++;
            else if (ones == 2 * k) ways2++;
        }
        return (int)((ways1 * ways2) % MOD);
    }
}

